function(container, apiUrl, tables) {
  // テーブルインデックス定義
  const STORES_TABLE = 1; // 店舗マスタ
  const PRODUCTS_TABLE = 2; // 商品マスタ
  const PREDICTION_RESULTS_TABLE = 8; // 需要予測結果
  const WEATHER_TABLE = 4; // 天候データ
  const EVENT_TABLE = 5; // イベントデータ

  // 予測結果テーブル再描画関数
  function renderPredictionResults(rows) {
    const tbody = container.querySelector('#prediction-table-body');
    tbody.innerHTML = rows.map(r => `
      <tr data-id="${r.id}">
        <td>${r.商品名 || '-'}</td>
        <td>${r.商品コード || '-'}</td>
        <td>${r.カテゴリ || '-'}</td>
        <td>${r.予測数量 || 0}</td>
        <td>${r.予測精度 || 0}%</td>
        <td>${r.推奨発注数量 || 0}</td>
        <td>${r.予測対象日 ? new Date(r.予測対象日).toLocaleDateString() : '-'}</td>
        <td>
          <button class="action-btn secondary detail-btn" data-id="${r.id}">詳細</button>
        </td>
      </tr>
    `).join('');
  }

  // 初期データ読み込み
  async function loadInitialData() {
    try {
      // 店舗データ読み込み
      const stores = await window.aivicApi.list(STORES_TABLE);
      const storeSelect = container.querySelector('#store-select');
      if (stores) {
        stores.forEach(store => {
          const option = document.createElement('option');
          option.value = store.id;
          option.textContent = store.店舗名 || store.name || `店舗${store.id}`;
          storeSelect.appendChild(option);
        });
      }

      // 商品カテゴリデータ読み込み（商品マスタから抽出）
      const products = await window.aivicApi.list(PRODUCTS_TABLE);
      const categorySelect = container.querySelector('#category-select');
      if (products) {
        const categories = [...new Set(products.map(p => p.商品カテゴリ || p.category).filter(Boolean))];
        categories.forEach(category => {
          const option = document.createElement('option');
          option.value = category;
          option.textContent = category;
          categorySelect.appendChild(option);
        });
      }

      // 予測結果データ読み込み
      const predictions = await window.aivicApi.list(PREDICTION_RESULTS_TABLE);
      if (predictions) {
        renderPredictionResults(predictions);
      }
    } catch (error) {
      console.error('初期データ読み込みエラー:', error);
    }
  }

  // バリデーション関数
  function validateForm() {
    const storeId = container.querySelector('#store-select').value;
    const category = container.querySelector('#category-select').value;
    const startDate = container.querySelector('#start-date').value;
    const endDate = container.querySelector('#end-date').value;
    const model = container.querySelector('#model-select').value;

    if (!storeId) {
      showError('店舗を選択してください');
      return false;
    }
    if (!category) {
      showError('商品カテゴリを選択してください');
      return false;
    }
    if (!startDate) {
      showError('予測期間の開始日を設定してください');
      return false;
    }
    if (!endDate) {
      showError('予測期間の終了日を設定してください');
      return false;
    }
    if (!model) {
      showError('予測モデルが選択されていません。予測モデルを選択してください。');
      return false;
    }
    if (new Date(startDate) >= new Date(endDate)) {
      showError('開始日は終了日より前の日付を設定してください');
      return false;
    }
    if (new Date(startDate) < new Date()) {
      showError('開始日は本日以降の日付を入力してください');
      return false;
    }

    return true;
  }

  // エラーメッセージ表示
  function showError(message) {
    const errorDiv = container.querySelector('#error-message');
    const errorText = container.querySelector('#error-text');
    errorText.textContent = message;
    errorDiv.classList.remove('hidden');
    setTimeout(() => {
      errorDiv.classList.add('hidden');
    }, 5000);
  }

  // 予測グラフ描画
  function drawPredictionChart(data) {
    const canvas = container.querySelector('#prediction-chart');
    const ctx = canvas.getContext('2d');

    // キャンバスクリア
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    if (!data || data.length === 0) return;

    const padding = 60;
    const chartWidth = canvas.width - padding * 2;
    const chartHeight = canvas.height - padding * 2;

    // データの最大値・最小値を取得
    const maxValue = Math.max(...data.map(d => d.value));
    const minValue = Math.min(...data.map(d => d.value));
    const valueRange = maxValue - minValue || 1;

    // 軸描画
    ctx.strokeStyle = '#9fb0d1';
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(padding, padding);
    ctx.lineTo(padding, padding + chartHeight);
    ctx.lineTo(padding + chartWidth, padding + chartHeight);
    ctx.stroke();

    // データポイント描画
    ctx.strokeStyle = '#4a90e2';
    ctx.lineWidth = 2;
    ctx.beginPath();

    data.forEach((point, index) => {
      const x = padding + (index / (data.length - 1)) * chartWidth;
      const y = padding + chartHeight - ((point.value - minValue) / valueRange) * chartHeight;

      if (index === 0) {
        ctx.moveTo(x, y);
      } else {
        ctx.lineTo(x, y);
      }
    });

    ctx.stroke();

    // ラベル描画
    ctx.fillStyle = '#9fb0d1';
    ctx.font = '12px Arial';
    ctx.textAlign = 'center';
    ctx.fillText('需要予測グラフ', canvas.width / 2, 30);
  }

  // 比較チャート描画
  function drawComparisonChart(actualData, predictedData) {
    const canvas = container.querySelector('#comparison-chart');
    const ctx = canvas.getContext('2d');

    ctx.clearRect(0, 0, canvas.width, canvas.height);

    const padding = 60;
    const chartWidth = canvas.width - padding * 2;
    const chartHeight = canvas.height - padding * 2;

    // 軸描画
    ctx.strokeStyle = '#9fb0d1';
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(padding, padding);
    ctx.lineTo(padding, padding + chartHeight);
    ctx.lineTo(padding + chartWidth, padding + chartHeight);
    ctx.stroke();

    // 凡例
    ctx.fillStyle = '#4a90e2';
    ctx.fillRect(padding, 20, 15, 15);
    ctx.fillStyle = '#9fb0d1';
    ctx.font = '12px Arial';
    ctx.textAlign = 'left';
    ctx.fillText('実績値', padding + 20, 32);

    ctx.fillStyle = '#e74c3c';
    ctx.fillRect(padding + 100, 20, 15, 15);
    ctx.fillStyle = '#9fb0d1';
    ctx.fillText('予測値', padding + 120, 32);
  }

  // AI予測実行
  async function executePrediction() {
    if (!validateForm()) return;

    const loadingIndicator = container.querySelector('#loading-indicator');
    const resultsDiv = container.querySelector('#prediction-results');
    const factorDiv = container.querySelector('#factor-analysis');

    // ローディング表示
    loadingIndicator.classList.remove('hidden');
    resultsDiv.classList.remove('hidden');

    try {
      const formData = {
        店舗ID: container.querySelector('#store-select').value,
        商品カテゴリ: container.querySelector('#category-select').value,
        予測対象日: container.querySelector('#start-date').value,
        予測期間終了日: container.querySelector('#end-date').value,
        予測モデルバージョン: container.querySelector('#model-select').value,
        季節性考慮: container.querySelector('#seasonal-check').checked,
        イベント考慮: container.querySelector('#event-check').checked,
        天候考慮: container.querySelector('#weather-check').checked,
        予測数量: Math.floor(Math.random() * 100) + 50, // サンプル予測値
        予測精度: Math.floor(Math.random() * 20) + 80, // 80-99%
        推奨発注数量: Math.floor(Math.random() * 80) + 40,
        予測ステータス: '完了',
        発注済フラグ: false
      };

      // 予測結果保存
      const saved = await window.aivicApi.save(PREDICTION_RESULTS_TABLE, formData);

      if (saved) {
        // 予測精度指標更新
        container.querySelector('#accuracy-value').textContent = `${formData.予測精度}%`;
        container.querySelector('#confidence-value').textContent = '95%';
        container.querySelector('#period-value').textContent = `${formData.予測対象日} - ${formData.予測期間終了日}`;

        // グラフ描画
        const sampleData = Array.from({length: 30}, (_, i) => ({
          date: new Date(Date.now() + i * 24 * 60 * 60 * 1000),
          value: Math.floor(Math.random() * 50) + formData.予測数量
        }));

        drawPredictionChart(sampleData);
        drawComparisonChart([], sampleData);

        // 影響要因分析表示
        factorDiv.classList.remove('hidden');
        container.querySelector('#weather-factors').innerHTML = '<p>気温: 中程度の影響 (+15%)</p><p>降水量: 軽微な影響 (-5%)</p>';
        container.querySelector('#event-factors').innerHTML = '<p>近隣イベント: 影響なし</p>';
        container.querySelector('#seasonal-factors').innerHTML = '<p>季節係数: 1.2 (春季需要増)</p>';

        // テーブル更新
        const predictions = await window.aivicApi.list(PREDICTION_RESULTS_TABLE);
        if (predictions) {
          renderPredictionResults(predictions);
        }
      }

    } catch (error) {
      showError('処理がタイムアウトしました。しばらく時間をおいて再度実行してください。');
    } finally {
      loadingIndicator.classList.add('hidden');
    }
  }

  // CSVエクスポート
  async function exportPredictionResults() {
    try {
      const predictions = await window.aivicApi.list(PREDICTION_RESULTS_TABLE);
      if (!predictions || predictions.length === 0) {
        showError('エクスポートするデータがありません');
        return;
      }

      const headers = ['商品名', '商品コード', 'カテゴリ', '予測数量', '予測精度', '推奨発注数量', '予測期間'];
      const csvContent = '\uFEFF' + headers.join(',') + '\n' + 
        predictions.map(row => [
          row.商品名 || '',
          row.商品コード || '',
          row.カテゴリ || '',
          row.予測数量 || 0,
          (row.予測精度 || 0) + '%',
          row.推奨発注数量 || 0,
          row.予測対象日 ? new Date(row.予測対象日).toLocaleDateString() : ''
        ].map(field => `"${field}"`).join(',')).join('\n');

      const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
      const link = document.createElement('a');
      link.href = URL.createObjectURL(blob);
      link.download = `需要予測結果_${new Date().toISOString().split('T')[0]}.csv`;
      link.click();
    } catch (error) {
      showError('エクスポートに失敗しました');
    }
  }

  // イベントリスナー登録
  container.querySelector('#btn-predict').addEventListener('click', executePrediction);

  container.querySelector('#btn-reset').addEventListener('click', () => {
    container.querySelector('#store-select').value = '';
    container.querySelector('#category-select').value = '';
    container.querySelector('#start-date').value = '';
    container.querySelector('#end-date').value = '';
    container.querySelector('#model-select').value = '';
    container.querySelector('#seasonal-check').checked = false;
    container.querySelector('#event-check').checked = false;
    container.querySelector('#weather-check').checked = false;
    container.querySelector('#prediction-results').classList.add('hidden');
    container.querySelector('#factor-analysis').classList.add('hidden');
  });

  container.querySelector('#btn-export').addEventListener('click', exportPredictionResults);

  // 行レベル操作のイベントデリゲーション
  container.addEventListener('click', async (e) => {
    const detailBtn = e.target.closest('.detail-btn');
    if (detailBtn) {
      const id = detailBtn.dataset.id;
      // 詳細画面への遷移
      window.showScreen('scr-1778591885672'); // AI需要予測処理画面
    }
  });

  // 初期データ読み込み実行
  loadInitialData();
}
